{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio (number of students per teacher). Primary independent variable. Computed as students / teachers; higher values mean more students per teacher (larger class sizes).",
        "columns": [
          "StudentTeacherRatio"
        ]
      }
    ],
    "dv": {
      "description": "District-level average academic performance. Constructed as the mean of the available standardized reading and math scores for 5th grade ('read' and 'math').",
      "columns": [
        "AvgScore"
      ]
    },
    "controls": [
      {
        "description": "Expenditure per student (district average). Controls for resource inputs per pupil.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "expenditure"
        ]
      },
      {
        "description": "District average income (in thousands). Controls for socioeconomic status of the district.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "income"
        ]
      },
      {
        "description": "Percent of English learners in the district. Controls for language composition which affects test performance.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english"
        ]
      },
      {
        "description": "Percent qualifying for reduced-price lunch. Controls for student poverty.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "lunch"
        ]
      },
      {
        "description": "Percent qualifying for CalWorks (income assistance). Another measure of student poverty.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "calworks"
        ]
      },
      {
        "description": "Number of computers per student in the district (computers / students). Controls for technology access.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ComputersPerStudent"
        ]
      },
      {
        "description": "Indicator for district grade span being KK-08 (1 if 'grades' == 'KK-08', 0 otherwise). Controls for structural differences between K-6 and K-8 districts.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Grades_KK08"
        ]
      },
      {
        "description": "County identifier. Included as a categorical control (county fixed effects will be encoded as dummies in the model). Controls for region-specific unobserved factors.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "county"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Ensure numeric columns are numeric\n    numeric_cols = ['students', 'teachers', 'read', 'math', 'computer', 'expenditure', 'income', 'english', 'lunch', 'calworks']\n    for col in numeric_cols:\n        if col in df.columns:\n            df[col] = pd.to_numeric(df[col], errors='coerce')\n\n    # Drop rows missing the core variables needed to compute IV and DV\n    df = df.dropna(subset=['students', 'teachers', 'read', 'math'])\n\n    # Compute dependent variable: average of reading and math scores\n    df['AvgScore'] = df[['read', 'math']].mean(axis=1)\n\n    # Compute independent variable: students per teacher\n    # Guard against division by zero\n    df['teachers'] = df['teachers'].replace({0: np.nan})\n    df['StudentTeacherRatio'] = df['students'] / df['teachers']\n\n    # Remove extreme or invalid ratios: set impossible or missing ratios to NaN\n    df.loc[~np.isfinite(df['StudentTeacherRatio']), 'StudentTeacherRatio'] = np.nan\n\n    # Winsorize StudentTeacherRatio at 1st and 99th percentiles to reduce influence of extreme outliers\n    if df['StudentTeacherRatio'].notna().sum() > 0:\n        lower = df['StudentTeacherRatio'].quantile(0.01)\n        upper = df['StudentTeacherRatio'].quantile(0.99)\n        df['StudentTeacherRatio'] = df['StudentTeacherRatio'].clip(lower=lower, upper=upper)\n\n    # Derived control: computers per student\n    df['ComputersPerStudent'] = df['computer'] / df['students']\n    df.loc[~np.isfinite(df['ComputersPerStudent']), 'ComputersPerStudent'] = np.nan\n\n    # Grade-span indicator: 1 if district covers KK-08, 0 otherwise\n    df['Grades_KK08'] = (df['grades'].astype(str) == 'KK-08').astype(int)\n\n    # Keep the county column as-is for later one-hot encoding in the model\n    # Drop rows that are missing critical controls (this reduces sample but avoids implicit imputation)\n    # We keep county even if missing (get_dummies will handle it), but drop rows missing key controls\n    df = df.dropna(subset=['StudentTeacherRatio', 'AvgScore', 'expenditure', 'income', 'english', 'lunch', 'calworks', 'ComputersPerStudent'])\n\n    # Reset index for cleanliness\n    df = df.reset_index(drop=True)\n\n    return df\n"
  ,
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    # Model the association between StudentTeacherRatio and AvgScore controlling for covariates\n    # Prepare outcome and covariates\n    # The transform step should have created the necessary columns; we still guard against missing data\n    required_cols = ['AvgScore', 'StudentTeacherRatio', 'expenditure', 'income', 'english', 'lunch', 'calworks', 'ComputersPerStudent', 'Grades_KK08', 'county']\n    for col in required_cols:\n        if col not in df.columns:\n            raise ValueError(f\"Required column {col} not found in dataframe\")\n\n    # Select baseline covariates\n    control_vars = ['expenditure', 'income', 'english', 'lunch', 'calworks', 'ComputersPerStudent', 'Grades_KK08']\n\n    X = df[['StudentTeacherRatio'] + control_vars].copy()\n    y = df['AvgScore'].copy()\n\n    # Encode county fixed effects as dummies (drop_first to avoid multicollinearity)\n    county_dummies = pd.get_dummies(df['county'].astype(str), prefix='county', drop_first=True)\n    if county_dummies.shape[1] > 0:\n        X = pd.concat([X, county_dummies], axis=1)\n\n    # Drop any remaining rows with missing values in X or y\n    data = pd.concat([X, y], axis=1).dropna()\n    X = data.drop(columns=['AvgScore'])\n    y = data['AvgScore']\n\n    # Add constant\n    X = sm.add_constant(X)\n\n    # Fit OLS with heteroskedasticity-robust (HC3) standard errors\n    model = sm.OLS(y, X)\n    results = model.fit(cov_type='HC3')\n\n    # Print a short summary and return the fitted results object\n    print(results.summary())\n    return results\n"
}

